// Import necessary classes
import com.mirth.connect.model.datatypes.Field;
import com.mirth.connect.model.datatypes.MapField;
import com.mirth.connect.util.MessageContext;

public class VitalSignsExtractor {

    public static void main(String[] args) {
        // Example message context (simulated)
        MessageContext messageContext = new MessageContext();

        // Simulate a sample ADT^A01 message
        String adtMessage = "MSH|^~\\&|SENDER|FACILITY|RECEIVER|FACILITY|20230401123456||ADT^A01|123456789|P|2.5.1\r"
                            + "PID|1||MRN^123456789^^^HOSPITAL^MRN|DOE^JOHN^M^III||19800101|M||||||||||||\r"
                            + "PV1|1|I|||||||||||||||||||||\r"
                            + "OBX|1|NM|8648-7^Body Weight^LN^LOINC|180.5||LBS||F\r"
                            + "OBX|2|NM|8302-2^Height^LN^LOINC|69.5||IN||F\r"
                            + "OBX|3|NM|71304-9^Body Mass Index (BMI) Calculation^LN^LOINC|25.0||\r";

        // Set the message in the context
        messageContext.setRawMessage(adtMessage);

        // Extract vital signs from OBX segments
        MapField vitalSigns = extractVitalSigns(messageContext);

        // Print the extracted vital signs
        for (String key : vitalSigns.keySet()) {
            System.out.println(key + ": " + vitalSigns.get(key));
        }
    }

    public static MapField extractVitalSigns(MessageContext messageContext) {
        try {
            // Get the raw message from the context
            String adtMessage = messageContext.getRawMessage();

            // Split the message into segments
            String[] segments = adtMessage.split("\r");

            // Initialize a map to store vital signs
            MapField vitalSigns = new MapField();

            // Iterate through each segment
            for (String segment : segments) {
                if (segment.startsWith("OBX")) {
                    // Split the OBX segment into fields
                    String[] fields = segment.split("\\|");

                    // Check if the observation identifier is one of the vital signs we're interested in
                    if ("8648-7".equals(fields[3]) || "8302-2".equals(fields[3]) || "71304-9".equals(fields[3])) {
                        // Extract the observation value and units
                        String observationValue = fields[5];
                        String units = fields[6];

                        // Store the vital sign in the map
                        switch (fields[3]) {
                            case "8648-7":
                                vitalSigns.put("Body Weight", observationValue + " " + units);
                                break;
                            case "8302-2":
                                vitalSigns.put("Height", observationValue + " " + units);
                                break;
                            case "71304-9":
                                vitalSigns.put("BMI", observationValue);
                                break;
                        }
                    }
                }
            }

            return vitalSigns;

        } catch (Exception e) {
            // Handle any exceptions that occur during extraction
            System.err.println("Error extracting vital signs: " + e.getMessage());
            return null;
        }
    }
}
```

