Below is a Python script using Mirth Connect's scripting capabilities (JavaScript) to extract the required fields from an HL7v2 message of type ADT^A04 for patient registration and update a new patient record in your database.

```javascript
// Import necessary libraries
const axios = require('axios');

function processHL7Message(message) {
    try {
        // Parse the HL7 message using Mirth's built-in parser
        const parsedMessage = parseHl7Message(message);

        // Extract required fields from PID-11 (Patient Address)
        const patientAddress = parsedMessage.PID[10]; // PID-11 is at index 10 in the array

        if (!patientAddress) {
            throw new Error('PID-11 not found in the HL7 message');
        }

        // Extract address components
        const streetAddress = patientAddress.split('^')[0];
        const city = patientAddress.split('^')[1];
        const stateProvince = patientAddress.split('^')[2];
        const zipCode = patientAddress.split('^')[3];

        // Format and validate the address components
        if (!streetAddress || !city || !stateProvince || !zipCode) {
            throw new Error('Invalid PID-11 format');
        }

        // Prepare data to be sent to the API
        const patientData = {
            streetAddress: streetAddress,
            city: city,
            stateProvince: stateProvince,
            zipCode: zipCode
        };

        // Make a POST request to update the patient record in your database
        axios.post('https://your-api-url/api/v1/patients', patientData)
            .then(response => {
                console.log('Patient record updated successfully:', response.data);
            })
            .catch(error => {
                throw new Error('Failed to update patient record:', error.message);
            });

    } catch (error) {
        // Handle any errors that occur during the process
        console.error('Error processing HL7 message:', error.message);
    }
}

// Function to parse an HL7 message using Mirth's built-in parser
function parseHl7Message(message) {
    return hl7.parse(message, '2.5'); // Assuming HL7 version 2.5
}

// Example usage
const hl7Message = `MSH|^~\&|SENDER|RECEIVER|ADT^A04|123456|20230401123456||ADT^A04^ADT_A04|123456789|P|2.5
PID|1||12345^MRN^M|^Doe^John^J||19800101|M||123 Main St^^Anytown^NY^12345^USA||123-456-7890^H`;

processHL7Message(hl7Message);
```

### Explanation:
1. **Parsing the HL7 Message**: The `parseHl7Message` function uses Mirth's built-in parser to convert the HL7 message into a JavaScript object.
2. **Extracting Address Components**: The script extracts the patient address from PID-11 and splits it into its components (Street, City, State/Province, ZIP Code).
3. **Formatting and Validation**: It checks if all required components are present and correctly formatted.
4. **Updating the Database**: The script makes a POST request to your API endpoint (`https://your-api-url/api/v1/patients`) to update the patient record with the extracted address information.
5. **Error Handling**: The script includes basic error handling to catch and log any issues that occur during the process.

### Notes:
- Replace `'https://your-api-url/api/v1/patients'` with your actual API endpoint URL.
- Ensure that the Mirth Connect environment has access to the `axios` library, which can be installed via npm if not already available.
- Adjust the HL7 version in the parser function as needed based on your specific requirements.

To extract the patient's home phone number from the PID segment of an ADT^A04 message and update it in a patient database, you can use Mirth Connect to create a script that processes the HL7 message and makes an HTTP PUT request to your API endpoint. Below is a sample script that demonstrates how to achieve this:

```javascript
// Import necessary modules
var http = new Packages.java.net.HttpURLConnection();
var url = new Packages.java.net.URL("https://your-api-endpoint.com/patients/{MRN}");

// Function to extract the home phone number from PID segment
function getHomePhoneNumber(hl7Message) {
    // Parse the HL7 message using Mirth's built-in API
    var pidSegment = hl7Message.get('PID');

    if (pidSegment == null) {
        throw new Error("PID segment not found in the HL7 message.");
    }

    // Extract the home phone number from PID-13
    var phoneNumber = pidSegment.getField(13);

    if (phoneNumber == null || phoneNumber.trim() === "") {
        throw new Error("Home phone number not found in the PID segment.");
    }

    return phoneNumber;
}

// Function to update patient information using HTTP PUT request
function updatePatientInDatabase(mrn, phoneNumber) {
    var url = new Packages.java.net.URL("https://your-api-endpoint.com/patients/" + mrn);
    var connection = url.openConnection();
    connection.setRequestMethod("PUT");
    connection.setRequestProperty("Content-Type", "application/json");
    connection.setDoOutput(true);

    // Create the JSON payload
    var jsonPayload = "{\"homePhoneNumber\":\"" + phoneNumber + "\"}";

    // Write the payload to the output stream
    var outputStream = connection.getOutputStream();
    outputStream.write(jsonPayload.getBytes());
    outputStream.flush();
    outputStream.close();

    // Get the response code
    var responseCode = connection.getResponseCode();

    if (responseCode !== 200) {
        throw new Error("Failed to update patient information. Response Code: " + responseCode);
    }
}

// Main script logic
try {
    // Extract the MRN from PID-3
    var pidSegment = message.get('PID');
    var mrn = pidSegment.getField(3);

    if (mrn == null || mrn.trim() === "") {
        throw new Error("MRN not found in the PID segment.");
    }

    // Extract the home phone number from the PID segment
    var phoneNumber = getHomePhoneNumber(message);

    // Update the patient information in the database
    updatePatientInDatabase(mrn, phoneNumber);

    logger.info("Successfully updated patient's home phone number for MRN: " + mrn);
} catch (e) {
    logger.error("Error processing HL7 message: " + e.message);
}
```

### Explanation:
1. **Extracting the Home Phone Number**:
   - The `getHomePhoneNumber` function parses the HL7 message to extract the home phone number from the PID-13 field.
   - It checks if the PID segment and the home phone number are present and throws an error if not.

2. **Updating Patient Information**:
   - The `updatePatientInDatabase` function constructs a JSON payload with the new home phone number and makes an HTTP PUT request to your API endpoint using Java's `HttpURLConnection`.
   - It handles potential errors such as network issues or invalid responses from the server.

3. **Main Script Logic**:
   - The main script logic extracts the MRN from the PID-3 field.
   - It calls the `getHomePhoneNumber` function to retrieve the home phone number.
   - It then calls the `updatePatientInDatabase` function to update the patient's information in the database.
   - Error handling is included to log any issues that occur during the processing of the HL7 message.

### Notes:
- Replace `"https://your-api-endpoint.com/patients/{MRN}"` with your actual API endpoint URL.
- Ensure that the Mirth Connect server has the necessary permissions to make HTTP requests and handle JSON payloads.
- Adjust the error handling and logging as per your specific requirements.

To fulfill the user's request, we need to extract the primary insurance company name from an IN1 segment in an ORU^R01 message and send it via a POST request to `/api/patient/insurance/update`. Below is a Python script using Mirth Connect's scripting capabilities to achieve this. This script assumes you have access to Mirth Connect's JavaScript API.

```javascript
// Import necessary libraries
var http = require('http');

function updatePatientInsurance(insuranceCompanyName) {
    // Define the URL and headers for the POST request
    var url = 'http://your-api-url/api/patient/insurance/update';
    var options = {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        }
    };

    // Create the data payload to be sent in the POST request
    var postData = JSON.stringify({
