import ca.uhn.hl7v2.DefaultHapiContext;
import ca.uhn.hl7v2.HL7Exception;
import ca.uhn.hl7v2.model.Message;
import ca.uhn.hl7v2.parser.Parser;
import ca.uhn.hl7v2.util.Terser;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

public class HL7v2LabResultParser {

    public static void main(String[] args) {
        String hl7Message = "MSH|^~\\&|SENDER|RECEIVER|ADT^A01|123456|20230401123456||ORU^R01|ABC123|P|2.5.1\r" +
                             "PID|1|MRN^123456789|SSN^123-45-6789|DOE^JOHN^M^^MRN^123456789||19800101|M||||||\r" +
                             "OBX|1|NM|LOINC^12345-6^Test Result^LN|1.23|U/L|1.0-2.0|H\r" +
                             "OBX|2|ST|LOINC^98765-4^Another Test^LN|Result Text||\r";

        try {
            List<LabResult> labResults = parseHL7Message(hl7Message);
            for (LabResult result : labResults) {
                System.out.println(result);
            }
        } catch (HL7Exception e) {
            e.printStackTrace();
        }
    }

    public static List<LabResult> parseHL7Message(String hl7Message) throws HL7Exception {
        DefaultHapiContext context = new DefaultHapiContext();
        Parser parser = context.getPipeParser();

        Message message = parser.parse(new StringReader(hl7Message));
        Terser terser = new Terser(message);

        List<LabResult> labResults = new ArrayList<>();

        // Check if the message is of type ORU^R01 or ADT^A01
        String messageType = terser.get("/MSH-9.0");
        if ("ORU^R01".equals(messageType) || "ADT^A01".equals(messageType)) {
            // Extract OBX segments
            int obxCount = terser.getCardinality("/OBX");
            for (int i = 1; i <= obxCount; i++) {
                LabResult result = new LabResult();
                result.setTestIdentifier(terser.getString("/OBX." + i + ".3.0"));
                result.setValue(terser.getString("/OBX." + i + ".5.0"));
                result.setUnits(terser.getString("/OBX." + i + ".6.0"));
                result.setReferenceRange(terser.getString("/OBX." + i + ".7.0"));
                result.setAbnormalFlag(terser.getString("/OBX." + i + ".8.0"));
                result.setStatus(terser.getString("/OBX." + i + ".11.0"));

                labResults.add(result);
            }
        }

        return labResults;
    }
}

