// Import necessary classes
import ca.uhn.hl7v2.model.Message;
import ca.uhn.hl7v2.model.v25.segment.MSH;
import ca.uhn.hl7v2.model.v25.segment.OBR;
import ca.uhn.hl7v2.model.v25.segment.ORC;
import ca.uhn.hl7v2.model.v25.segment.PID;
import ca.uhn.hl7v2.parser.Parser;
import ca.uhn.hl7v2.util.Hl7Util;

public class HL7OrderProviderExtractor {

    public static String extractOrderingProvider(Message hl7Message) {
        try {
            // Get the MSH segment
            MSH mshSegment = (MSH) hl7Message.get("MSH");

            // Check if the message type is ADT^A01
            if (!"ADT".equals(mshSegment.getMessageType().getMessageType()) || !"A01".equals(mshSegment.getMessageType().getTriggerEvent())) {
                throw new IllegalArgumentException("Invalid message type. Expected ADT^A01.");
            }

            // Get the ORC segments
            List<ORC> orcSegments = hl7Message.getAll("ORC");

            if (orcSegments.isEmpty()) {
                throw new IllegalStateException("No ORC segments found in the message.");
            }

            // Iterate through ORC segments to find the correct one based on MSH-10
            String messageControlID = mshSegment.getMessageControlID().getValue();
            for (ORC orcSegment : orcSegments) {
                if (orcSegment.getOrderControl().getValue().equals("NW") && 
                    orcSegment.getPlacerOrderNumber().getIDNumber().getValue().equals(messageControlID)) {

                    // Get the ordering provider's name
                    String orderingProviderName = getProviderName(orcSegment);
                    return orderingProviderName;
                }
            }

            throw new IllegalStateException("No matching ORC segment found for the given message control ID.");
        } catch (Exception e) {
            e.printStackTrace();
            return null; // Handle or log error appropriately
        }
    }

    private static String getProviderName(ORC orcSegment) {
        try {
            // Get the OBR segments associated with this ORC segment
            List<OBR> obrSegments = orcSegment.getAll("OBR");

            if (obrSegments.isEmpty()) {
                throw new IllegalStateException("No OBR segments found for the given ORC segment.");
            }

            // Iterate through OBR segments to find the correct one based on Filler Order Number
            String fillerOrderNumber = orcSegment.getFillerOrderNumber().getIDNumber().getValue();
            for (OBR obrSegment : obrSegments) {
                if (obrSegment.getPlacerOrderNumber().getIDNumber().getValue().equals(fillerOrderNumber)) {

                    // Get the ordering provider's name
                    PID pidSegment = (PID) obrSegment.getParent().getParent().get("PID");
                    String familyName = pidSegment.getPatientName(0).getFamilyName().getSurname().getValue();
                    String givenName = pidSegment.getPatientName(0).getGivenName(0).getValue();

                    return "Dr. " + familyName + ", " + givenName;
                }
            }

            throw new IllegalStateException("No matching OBR segment found for the given filler order number.");
        } catch (Exception e) {
            e.printStackTrace();
            return null; // Handle or log error appropriately
        }
    }

    public static void main(String[] args) {
        // Example usage within a Mirth Connect channel script
        Message hl7Message = Hl7Util.parse("your_hl7_message_here");
        String orderingProviderName = extractOrderingProvider(hl7Message);
        System.out.println(orderingProviderName);
    }
}
```

