import ca.uhn.hl7v2.model.Message;
import ca.uhn.hl7v2.model.v25.segment.PID;
import ca.uhn.hl7v2.parser.Parser;
import ca.uhn.hl7v2.util.HL7Exception;

public class PhoneNumberExtractor {

    /**
     * Extracts the patient's phone number from the PID-13 field of an ADT^A04 message
     * and formats it as a standard E.164 number.
     *
     * @param hl7Message The HL7 message to process.
     * @return The formatted phone number or null if not found or invalid.
     */
    public static String extractAndFormatPhoneNumber(Message hl7Message) {
        try {
            // Ensure the message is an ADT^A04
            if (!"ADT".equals(hl7Message.getMSH().getMessageType().getTriggerEvent()) ||
                !"A04".equals(hl7Message.getMSH().getMessageType().getIdentificationCode())) {
                throw new IllegalArgumentException("Invalid HL7 message type. Expected ADT^A04.");
            }

            // Get the PID segment
            PID pid = hl7Message.getPID();
            if (pid == null) {
                throw new IllegalStateException("PID segment not found in the message.");
            }

            // Extract the phone number from PID-13
            String phoneNumber = pid.getPhoneNumberHome().getValue();

            if (phoneNumber == null || phoneNumber.isEmpty()) {
                return null;
            }

            // Format the phone number as E.164
            String formattedPhoneNumber = formatToE164(phoneNumber);

            return formattedPhoneNumber;

        } catch (HL7Exception e) {
            // Handle HL7 parsing exceptions
            System.err.println("Error processing HL7 message: " + e.getMessage());
            return null;
        }
    }

    /**
     * Formats a phone number to E.164 format.
     *
     * @param phoneNumber The phone number to format.
     * @return The formatted phone number or null if invalid.
     */
    private static String formatToE164(String phoneNumber) {
        // Remove non-digit characters
        phoneNumber = phoneNumber.replaceAll("[^0-9]", "");

        // Check if the number has 10 digits (US standard)
        if (phoneNumber.length() != 10) {
            System.err.println("Invalid phone number length. Expected 10 digits.");
            return null;
        }

        // Format as E.164: +1-XXX-XXX-XXXX
        return "+1-" + phoneNumber.substring(0, 3) + "-" + phoneNumber.substring(3, 6) + "-" + phoneNumber.substring(6);
    }

    public static void main(String[] args) {
        // Example usage
        String hl7Message = "MSH|^~\\&|SENDER|RECEIVER|ADT^A04|12345|20230401123456||ADT^A04|1234567890|P|2.5.1\r" +
                            "PID|1||MRN^12345^MRN^I|LAST^FIRST^MIDDLE|M|F|19900101|M||123 Main St^^City^ST^ZIP|123-456-7890\r" +
                            "PV1|1|O||||||||||||||||||||\r";

        try {
            Parser parser = ca.uhn.hl7v2.parser.Parser.getParser(hl7Message);
            Message message = parser.parse(hl7Message);

            String phoneNumber = extractAndFormatPhoneNumber(message);
            if (phoneNumber != null) {
                System.out.println("Formatted Phone Number: " + phoneNumber);
            } else {
                System.out.println("Phone number not found or invalid.");
            }
        } catch (HL7Exception e) {
            System.err.println("Error parsing HL7 message: " + e.getMessage());
        }
    }
}
```

