const express = require('express');
const mllp = require('mllp');

const app = express();
app.use(express.json());

// Function to parse HL7v2 message and extract OBX segments
function parseOBXSegments(hl7Message) {
    const obxSegments = [];
    const lines = hl7Message.split('\r');
    for (let line of lines) {
        if (line.startsWith('OBX')) {
            const fields = line.split('|');
            obxSegments.push({
                observationIdentifier: fields[3],
                valueType: fields[2],
                observationValue: fields[5],
                units: fields[6],
                referenceRange: fields[7]
            });
        }
    }
    return obxSegments;
}

// API endpoint to extract lab results
