    const hl7Message = req.body.hl7Message;

    if (!hl7Message) {
        return res.status(400).json({ error: 'HL7 message is required' });
    }

    // Parse the HL7 message to extract OBX segments
    try {
        const obxSegments = parseOBXSegments(hl7Message);
        const response = {
            messageControlID: hl7Message.split('\r')[0].split('|')[10],
            labResults: obxSegments
        };
        res.json(response);
    } catch (error) {
        res.status(500).json({ error: 'Failed to parse HL7 message', details: error.message });
    }
});

