                "url": "Patient/example"
            },
            "resource": patient_resource
        },
        {
            "request": {
                "method": "POST",  # Use POST to create a new resource if it doesn't exist
                "url": "Encounter"
            },
            "resource": encounter_resource
        }
    ]
}

# Convert the bundle to JSON format
bundle_json = json.dumps(bundle, indent=2)

# Send the transaction bundle to the FHIR server
response = requests.post(f"{FHIR_SERVER_URL}/Bundle", headers=headers, data=bundle_json)

# Check the response status code and print the result
if response.status_code == 201:
    print("Transaction bundle submitted successfully.")
    print("Response:", response.json())
elif response.status_code == 200:
    print("Patient resource updated successfully.")
    print("Response:", response.json())
else:
    print(f"Error submitting transaction bundle: {response.status_code}")
    print("Response:", response.text)
```

