 * @param {String} toEmail - Email address of the healthcare provider
 * @param {String} patientName - Patient's name
 * @param {String} mrn - Patient's MRN
 * @param {Array} criticalResults - Array of critical results details
 */
function sendEmailAlert(toEmail, patientName, mrn, criticalResults) {
    try {
        var fromEmail = 'your-email@example.com'; // Replace with your email address
        var password = 'your-email-password'; // Replace with your email password

        var message = new MimeMessage(Session);
        message.setFrom(new mail.internet.InternetAddress(fromEmail));
        message.addRecipient(mail.Message.RecipientType.TO, new mail.internet.InternetAddress(toEmail));

        var subject = 'Critical Lab Results Alert for Patient: ' + patientName;
        var body = 'Patient Name: ' + patientName + '\n';
        body += 'MRN: ' + mrn + '\n\n';
        body += 'Critical Lab Results:\n';

        criticalResults.forEach(function(result) {
            body += result + '\n';
        });

        message.setSubject(subject);
        message.setText(body);

        var transport = mail.Session.getDefaultInstance(Properties).getTransport('smtp');
        transport.connect('smtp.example.com', 587, fromEmail, password); // Replace with your SMTP server details
        transport.sendMessage(message, message.getAllRecipients());
        transport.close();
    } catch (e) {
        logger.error('Error sending email: ' + e);
    }
}

