    // List of LOINC codes indicating critical results
    var criticalCodes = [
        "10964-5",  // Hemoglobin A1c (HbA1c)
        "2708-6",   // Glucose Fasting
        "3094-0",   // Blood Pressure Systolic
        "8462-4"    // Blood Pressure Diastolic
    ];

    return criticalCodes.includes(resultCode);
}

