Certainly! Below is a JavaScript transformer for Mirth Connect designed to handle HL7 messages from a laboratory system. The transformer will extract critical test results (glucose levels above 200 mg/dL or below 40 mg/dL) and send an email alert if such a result is detected.

```javascript
// Import necessary Java classes
importPackage(java.util);
importPackage(java.text);

/**
 * Function to extract patient data from HL7 message
 * @param {Object} msg - The HL7 message object
 * @return {Object} - An object containing patient data
 */
function extractPatientData(msg) {
    var patientName = msg['PID']['PID.5']['PID.5.1'].toString();  // Family name
    var mrn = msg['PID']['PID.3']['PID.3.1'].toString();          // MRN
    var dob = msg['PID']['PID.7']['PID.7.1'].toString();          // Date of birth

    return {
        patientName: patientName,
        mrn: mrn,
        dob: dob
    };
}

/**
 * Function to extract critical test results from HL7 message
 * @param {Object} msg - The HL7 message object
 * @return {Array} - An array of objects containing critical test results
 */
function extractCriticalResults(msg) {
    var criticalResults = [];
    for each (var obx in msg['OBX']) {
        var resultValue = parseFloat(obx['OBX.5']['OBX.5.1'].toString());
        var units = obx['OBX.6']['OBX.6.1'].toString();
        var testCode = obx['OBX.3']['OBX.3.1'].toString();

        if (testCode === '8462-4' && (resultValue > 200 || resultValue < 40)) {
            criticalResults.push({
                testCode: testCode,
                resultValue: resultValue,
                units: units
            });
        }
    }

    return criticalResults;
}

/**
 * Function to send an email alert
 * @param {String} patientName - The patient's name
 * @param {String} mrn - The patient's MRN
 * @param {Date} testDate - The date of the test
 * @param {Array} results - An array of critical test results
 */
function sendEmailAlert(patientName, mrn, testDate, results) {
    var smtpServer = 'smtp.example.com';
    var port = 587;
    var username = 'integration_user';
    var password = 'integration_pass';

    var subject = 'Critical Lab Result Alert';
    var body = 'Patient Name: ' + patientName + '\n' +
               'MRN: ' + mrn + '\n' +
               'Test Date: ' + testDate.toISOString() + '\n' +
               'Results:\n';

    for each (var result in results) {
        body += '  Test Code: ' + result.testCode + '\n' +
                '  Result Value: ' + result.resultValue + ' ' + result.units + '\n';
    }

    var message = new Packages.javax.mail.internet.MimeMessage(new Packages.javax.mail.Session(
        new Packages.java.util.Properties(), null
    ));
    message.setFrom(new Packages.javax.mail.internet.InternetAddress(username));
    message.addRecipient(Packages.javax.mail.Message.RecipientType.TO, 
        new Packages.javax.mail.internet.InternetAddress('alert@example.com'));
    message.setSubject(subject);
    message.setText(body);

    var transport = Packages.javax.mail.Transport.getInstance(
        'smtp', new Packages.javax.mail.Authenticator() {
            override getPasswordAuthentication() {
                return new Packages.javax.mail.PasswordAuthentication(username, password);
            }
        }
    );
    transport.connect(smtpServer, port, username, password);
    transport.sendMessage(message, message.getAllRecipients());
    transport.close();
}

/**
 * Main transformer function
 */
function transform(msg, type, metadata) {
    try {
        var patientData = extractPatientData(msg);
        var results = extractCriticalResults(msg);

        if (results.length > 0) {
            sendEmailAlert(patientData.patientName, patientData.mrn, new Date(), results);
        }
    } catch (e) {
        logger.error('Error processing HL7 message: ' + e.message);
    }

    return msg;
}
```

### Explanation:

1. **extractPatientData**: This function extracts the patient's name, MRN, and date of birth from the HL7 message.
2. **extractCriticalResults**: This function iterates through the OBX segments to find critical test results (glucose levels above 200 mg/dL or below 40 mg/dL) with a specific test code ('8462-4').
3. **sendEmailAlert**: This function sends an email alert using SMTP. It constructs the email subject and body, then uses JavaMail to send the email.
4. **transform**: The main transformer function that orchestrates the extraction of patient data and critical results, and calls the email sending function if any critical results are found.

### Error Handling:
- The `try-catch` block around the main logic ensures that any errors during message processing or email sending are logged without crashing the transformer.

### Notes:
- Ensure that the SMTP server details and credentials are correct.
- Adjust the test code ('8462-4') if it differs in your actual HL7 messages.
- The email recipient ('alert@example.com') should be replaced with the appropriate address for alerts.

