var DB_QUERY_UPDATE = "UPDATE patients SET name = ?, contact_info = ? WHERE patient_id = ?";
var DB_QUERY_INSERT = "INSERT INTO patients (mrn, name, contact_info) VALUES (?, ?, ?)";

// Define the error message keys
var ERROR_MESSAGE_DB_CONNECTION = 'Error connecting to database';
var ERROR_MESSAGE_DB_QUERY = 'Error executing database query';

