            var name = msg['PID']['PID.5']['PID.5.1'].toString();  // Family name
            var contactInfo = msg['PD1']['PD1.7']['PD1.7.3'].toString();  // Contact info

            dbConn.executeUpdate(DB_QUERY_INSERT, [mrn, name, contactInfo]);
        }
    } catch (e) {
        logger.error(ERROR_MESSAGE_DB_QUERY + ': ' + e.message);
        throw e;
    } finally {
        // Close the database connection
        dbConn.close();
    }
