```javascript
// Import necessary libraries
var java = Packages.java;
var javax.mail;
var javax.mail.internet;

// Function to send email
function sendEmail(patientName, mrn, labResults) {
    try {
        // SMTP server configuration
        var smtpHost = 'smtp.example.com';
        var smtpPort = 587;
        var smtpUser = 'lab_alerts';
        var smtpPassword = 'alert123!';

        // Create a session with the SMTP server
        var props = java.util.Properties();
        props.put('mail.smtp.host', smtpHost);
        props.put('mail.smtp.port', smtpPort);
        props.put('mail.smtp.auth', 'true');
        props.put('mail.smtp.starttls.enable', 'true');

        var auth = new javax.mail.Authenticator() {
            getPasswordAuthentication: function() {
                return new javax.mail.PasswordAuthentication(smtpUser, smtpPassword);
            }
        };

        var session = javax.mail.Session.getInstance(props, auth);

        // Create a message
        var message = new javax.mail.internet.MimeMessage(session);
        message.setFrom(new javax.mail.internet.InternetAddress('no-reply@example.com'));
        message.addRecipient(javax.mail.Message.RecipientType.TO, new javax.mail.internet.InternetAddress('alert_recipient@example.com'));
        message.setSubject('Critical Lab Results Alert');
        message.setText('Patient Name: ' + patientName + '\nMRN: ' + mrn + '\nLab Results:\n' + labResults);

        // Send the message
        var transport = session.getTransport('smtp');
        transport.connect(smtpHost, smtpPort, smtpUser, smtpPassword);
        transport.sendMessage(message, message.getAllRecipients());
        transport.close();

        logger.info('Email sent successfully.');
    } catch (e) {
        logger.error('Failed to send email: ' + e.message);
    }
}

// Main script logic
try {
    // Access HL7 segments
    var patientName = msg['PID']['PID.5']['PID.5.1'].toString();  // Family name
    var mrn = msg['PID']['PID.3']['PID.3.1'].toString();          // MRN

    // Initialize variables to store critical lab results
    var criticalResults = '';

    // Access repeating segments (OBX)
    for each (var obx in msg['OBX']) {
        var resultValue = obx['OBX.5']['OBX.5.1'].toString();
        var units = obx['OBX.6']['OBX.6.1'].toString();
        var criticalFlag = obx['OBX.7']['OBX.7.1'].toString();

        // Check if the result is critical
        if (criticalFlag === 'CR') {
            criticalResults += 'Test: ' + obx['OBX.3']['OBX.3.1'].toString() + ', Value: ' + resultValue + ' ' + units + '\n';
        }
    }

    // Check if any critical results were found
    if (criticalResults !== '') {
        sendEmail(patientName, mrn, criticalResults);
    } else {
        logger.info('No critical lab results detected.');
    }
} catch (e) {
    logger.error('Error processing HL7 message: ' + e.message);
}
```

