To develop a script that triggers an automated email notification when a patient's vital signs exceed predefined thresholds, we will use Mirth Connect to receive HL7 v2.5 messages, compare the observations against configured limits, and send an email if any threshold is exceeded. We will also retrieve the latest vital sign data from the FHIR API endpoint.

Here's the production-quality code for the script:

```javascript
// Import necessary libraries
var EmailSender = Packages.com.mirth.connect.plugins.email.EmailSender;
var HttpClient = Packages.java.net.HttpURLConnection;

// Configuration parameters
var emailConfig = {
    host: 'smtp.example.com',
    port: 587,
    username: 'your-email@example.com',
    password: 'your-password',
    fromEmail: 'your-email@example.com'
};

var vitalSignsThresholds = {
    heartRate: { lower: 60, upper: 100 },
    bloodPressure: { lower: 90, upper: 140 },
    respiratoryRate: { lower: 12, upper: 20 }
};

// Function to send email
function sendEmail(patientId, vitalSign, value) {
    var subject = 'Vital Sign Alert for Patient ID: ' + patientId;
    var body = 'Patient ID: ' + patientId + '\n' +
               'Time of Observation: ' + new Date() + '\n' +
               'Vital Sign Exceeded: ' + vitalSign + '\n' +
               'Current Value: ' + value + '\n\n' +
               'View Full Observation in EMR: http://your-emr-url/Observation?patient=' + patientId + '&category=vital-signs&code=http://loinc.org|8867-4\n' +
               'Alert/Intervention Links: [Add relevant links here]';

    var emailSender = new EmailSender(emailConfig.host, emailConfig.port, emailConfig.username, emailConfig.password);
    emailSender.sendEmail(emailConfig.fromEmail, ['on-call-doctor@example.com'], subject, body);
}

// Function to retrieve latest vital signs data from FHIR API
function getLatestVitalSigns(patientId) {
    var url = 'http://your-fhir-api-url/Observation?patient=' + patientId + '&category=vital-signs&code=http://loinc.org|8867-4';
    var connection = HttpClient.newURLConnection(new java.net.URL(url));
    connection.setRequestMethod('GET');
    connection.setRequestProperty('Authorization', 'Bearer your-fhir-api-token');

    try {
        var responseCode = connection.getResponseCode();
        if (responseCode === 200) {
            var inputStream = connection.getInputStream();
            var reader = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(inputStream));
            var jsonResponse = '';
            var line;
            while ((line = reader.readLine()) !== null) {
                jsonResponse += line;
            }
            reader.close();
            return JSON.parse(jsonResponse);
        } else {
            throw new Error('Failed to retrieve vital signs data. Response code: ' + responseCode);
        }
    } catch (e) {
        log.error('Error retrieving vital signs data: ', e);
        throw e;
    } finally {
        connection.disconnect();
    }
}

// Main script logic
function onMessage(message) {
    var hl7Message = message.getPayloadAsString();

    // Parse HL7 message to extract patient ID and observations
    var patientId = hl7Message.match(/PID.*?ID\|([^\|]+)/)[1];
    var vitalSigns = [
        { code: '8867-4', name: 'Heart Rate' },
        { code: '85354-9', name: 'Blood Pressure' },
        { code: '9279-1', name: 'Respiratory Rate' }
    ];

    for (var i = 0; i < vitalSigns.length; i++) {
        var observationCode = vitalSigns[i].code;
        var observationName = vitalSigns[i].name;

        // Retrieve latest vital signs data from FHIR API
        var fhirData = getLatestVitalSigns(patientId);

        // Check if the latest observation exceeds the threshold
        for (var j = 0; j < fhirData.entry.length; j++) {
            var entry = fhirData.entry[j];
            var code = entry.resource.code.coding[0].code;
            var value = entry.resource.valueQuantity.value;

            if (code === observationCode) {
                var threshold = vitalSignsThresholds[observationName.toLowerCase()];

                if (value < threshold.lower || value > threshold.upper) {
                    sendEmail(patientId, observationName, value);
                }
            }
        }
    }
}
```

