### Step 2: Parse the HL7 message to extract relevant data

Create a function to parse the HL7 message:

```javascript
function parseHL7(hl7Message) {
  const parsedData = {};

  // Extract MSH segment
  const mshSegment = hl7Message.split('\r').find(segment => segment.startsWith('MSH'));
  if (mshSegment) {
    parsedData.msh = extractSegmentFields(mshSegment);
  }

  // Extract PID segment
  const pidSegment = hl7Message.split('\r').find(segment => segment.startsWith('PID'));
  if (pidSegment) {
    parsedData.pid = extractSegmentFields(pidSegment);
  }

  // Extract OBX segments
  const obxSegments = hl7Message.split('\r').filter(segment => segment.startsWith('OBX'));
  if (obxSegments.length > 0) {
    parsedData.obx = obxSegments.map(extractSegmentFields);
  }

  return parsedData;
}

function extractSegmentFields(segment) {
  const fields = segment.split('|');
  return fields.map(field => field.trim());
}
```

