    public void convertAndSendHL7ToFHIR(String hl7Message) {
        try {
            // Parse the HL7 message
            DefaultHapiContext context = new DefaultHapiContext();
            Message parsedMessage = context.getPipeParser().parse(hl7Message);

            // Extract MSH segment for timestamp and sending/receiving application details
            MSH mshSegment = (MSH) parsedMessage.get("MSH");
            String timestamp = mshSegment.getMsh2DateTimeOfMessage().getTimeOfEvent().getValue();
            String sendingApplication = mshSegment.getMsh3SendingApplication().getNamespaceID().getValue();
            String receivingApplication = mshSegment.getMsh4ReceivingApplication().getNamespaceID().getValue();

            // Extract PID segment for patient demographic information
            PID pidSegment = (PID) parsedMessage.get("PID");
            String patientName = pidSegment.getPid5PatientName(0).getXpnFamilyName().getXpnSurname().getValue();
            String patientId = pidSegment.getPid3PatientIdentifierList(0).getPid3_1UniversalID().getValue();

            // Create a JSON payload
