    "87654-3": {"code": "87654-3", "display": "Serum Creatinine"},
    "1092-6": {"code": "1092-6", "display": "Body Weight"}
};

// Define the function to convert HL7 v2.5.1 ADT^A01 message to FHIR JSON
function convertToFhirJson(message) {
    var fhirObservations = [];

    // Extract patient information from PID segment
    var pidSegments = message.get("PID");
    if (pidSegments.length > 0) {
        var pidSegment = pidSegments[0];
        var patientId = pidSegment.getField(3, 1); // PID-3-Patient ID - Type/ID
        var patientName = pidSegment.getField(5, 0); // PID-5-Patient Name

        // Extract OBX segments and map to FHIR Observations
        var obxSegments = message.get("OBX");
        for (var i = 0; i < obxSegments.length; i++) {
            var obxSegment = obxSegments[i];
            var observationCode = obxSegment.getField(3); // OBX-3-Observation Identifier - ID
            var observationValue = obxSegment.getField(5); // OBX-5-Observation Value

            if (obxToFhirObservationMap[observationCode]) {
                var fhirObservation = {
                    "resourceType": "Observation",
                    "id": patientId + "-obs-" + i,
                    "status": "final",
                    "category": [{"coding": [{"system": "http://terminology.hl7.org/CodeSystem/observation-category", "code": "laboratory"}]}],
                    "code": {"coding": [{"system": "http://loinc.org", "code": obxToFhirObservationMap[observationCode].code, "display": obxToFhirObservationMap[observationCode].display}]},
                    "subject": {"reference": "Patient/" + patientId},
                    "effectiveDateTime": message.get("MSH").getField(7), // MSH-7-Sending Application
                    "valueQuantity": {
                        "value": observationValue,
                        "unit": obxSegment.getField(6), // OBX-6-Observation Units
                        "system": "http://unitsofmeasure.org",
                        "code": obxSegment.getField(6)
                    }
                };

                fhirObservations.push(fhirObservation);
            }
        }
    }

    return JSON.stringify({"resourceType": "Bundle", "type": "batch", "entry": fhirObservations.map(observation => ({ "fullUrl": observation.id, "resource": observation }))});
}

// Define the channel processor
function processMessage(message) {
    try {
        var fhirJson = convertToFhirJson(message);

        // Send FHIR JSON to patient management system's API endpoint
        var response = httpSender.send(fhirJson);

        if (response.getStatusCode() >= 200 && response.getStatusCode() < 300) {
            logger.info("Successfully sent FHIR message to patient management system");
