            throw new Error("Failed to send FHIR message to patient management system: " + response.getStatusText());
        }
    } catch (error) {
        logger.error("Error processing HL7 message: " + error.message);

        // Retry the message if configured
        if (channelConfig.errorHandling.retryAttempts > 0) {
            channel.retryMessage();
        }
    }
}

// Set the channel processor
setChannelProcessor(processMessage);
