    msh.MSH_5_SendingApplication.setNamespaceId("EHRSystem");
    msh.MSH_6_ReceivingApplication.setNamespaceId("HealthcareFacility");
    msh.MSH_7_SendingFacility.setNamespaceId("EHRSystem");
    msh.MSH_8_ReceivingFacility.setNamespaceId("HealthcareFacility");
    msh.MSH_9_MessageType.setTriggerEvent("ADT^A01");
    msh.MSH_10_MessageControlID.setControlID(new Date().getTime());
    msh.MSH_11_ProcessingID.setProcessingID("P");
    msh.MSH_12_VersionID.setVersionID("2.5");

    var evn = new EVN();
    evn.EVN_1_EventTypeCode.setEventCode("A01");

    var pid = new PID();
    pid.PID_3_PatientName.addXPN(patient.name);
    pid.PID_5_DateTimeOfBirth.setTimeStamp("Z");
    pid.PID_7_Gender.setGender(patient.gender);

    var pd1 = new PD1();
    pd1.PD1_2_Sex.setSex(patient.gender);

    var obr = new OBR();
    obr.OBR_3_PlacerOrderNumber.addEIP(patient.orderNumber);
    obr.OBR_4_FillerOrderNumber.addEIP(patient.orderNumber);
    obr.OBR_5_OrderDateTime.setTimeStamp("Z");
    obr.OBR_6_OrderingProvider.setNamespaceId(patient.providerID);

    return {
        MSH: msh,
        EVN: evn,
        PID: pid,
        PD1: pd1,
        OBR: obr
    };
}

function generateADTMessage(patient) {
    var segmentData = getSegmentData(patient);
    var adtMessage = new ADT();
    adtMessage.addMSH(segmentData.MSH);
    adtMessage.addEVN(segmentData.EVN);
    adtMessage.addPID(segmentData.PID);
    adtMessage.addPD1(segmentData.PD1);
    adtMessage.addOBR(segmentData.OBR);

    return adtMessage.toString();
}

function getPatientData() {
    // Fetch patient data from your EHR system
    var patient = {
        name: "John Doe",
        gender: "M",
        orderNumber: "ORD123456",
        providerID: "PROV7890"
    };
    return patient;
}

function onReceive(message) {
    var patient = getPatientData();
    var adtMessage = generateADTMessage(patient);

    // Add the ADT message to a FHIR Bundle
    var fhirBundle = new FHIR.Bundle();
    fhirBundle.addEntry(new FHIR.Entry(adtMessage));

    // Convert the FHIR Bundle to JSON
    var fhirJson = fhirBundle.toString();

    // Send the FHIR Bundle to the remote healthcare facility's FHIR API
    try {
        var response = sendFHIRRequest(fhirJson);
        if (response.status === 201) {
            logger.info("ADT message submitted successfully");
        } else {
            logger.error("Failed to submit ADT message: " + response.text);
        }
    } catch (e) {
        logger.error("Error sending FHIR request: " + e.message);
    }

    return message;
}

function sendFHIRRequest(fhirJson) {
    var url = getDefaultProperties().fhirAPIUrl.replace("{patientID}", getDefaultProperties().patientID);
    var headers = {
        "Authorization": "Bearer " + getDefaultProperties().bearerToken,
        "Content-Type": "application/fhir+json"
    };

    return HTTPUtil.send({
        url: url,
        method: "POST",
        contentType: "application/json",
        data: fhirJson,
        headers: headers
    });
}
