To convert an ADT^A01 message to a FHIR Patient resource and post it to a healthcare platform's FHIR server, you can use Mirth Connect along with JavaScript for the transformation logic. Below is a sample script that demonstrates how to achieve this:

```javascript
// Import necessary libraries
var hl7 = new Packages.ca.uhn.hl7v2.model.v25.message.ADT_A01();
var fhir = Packages.org.hl7.fhir.r4.model;

// Function to convert ADT^A01 message to FHIR Patient resource
function adtToFhirPatient(message) {
    var pid = message.getPID(1); // Get the first PID segment

    // Create a new FHIR Patient resource
    var patient = new fhir.Patient();

    // Set the patient's name (PID-5)
    var names = pid.getXPNAll();
    for (var i = 0; i < names.length; i++) {
        var name = names[i];
        var humanName = new fhir.HumanName();
        humanName.addFamily(name.getFN1().getSurname().getValue());

        if (name.getFN2() != null) {
            humanName.addGiven(name.getFN2().getGivenAsSingleString());
        }

        if (name.getFN3() != null) {
            humanName.setPrefix(name.getFN3().getTitle().getValue());
        }

        patient.addName(humanName);
    }

    // Set the patient's birthdate (PID-7)
    var birthDate = pid.getDTM(7).getTime();
    if (birthDate != null) {
        patient.setBirthDate(new Date(birthDate));
    }

    return patient;
}

// Main script logic
try {
    // Parse the incoming ADT^A01 message
    var adtMessage = new Packages.ca.uhn.hl7v2.model.v25.message.ADT_A01(msg);

    // Convert the ADT^A01 message to FHIR Patient resource
    var fhirPatient = adtToFhirPatient(adtMessage);

    // Serialize the FHIR Patient resource to JSON
    var jsonPatient = Packages.org.hl7.fhir.r4.formats.JsonParser().setPrettyPrint(true).encodeResourceToString(fhirPatient);

    // Log the FHIR Patient resource for debugging purposes
    logger.info("FHIR Patient Resource: " + jsonPatient);

    // Post the FHIR Patient resource to the healthcare platform's FHIR server
    var url = "https://api.healthcareplatform.com/fhir/Patient";
    var client = new Packages.org.apache.http.impl.client.HttpClients.createDefault();
    var postRequest = new Packages.org.apache.http.client.methods.HttpPost(url);
    var jsonEntity = new Packages.org.apache.http.entity.StringEntity(jsonPatient, 'UTF-8');
    postRequest.setEntity(jsonEntity);
    postRequest.setHeader('Content-Type', 'application/fhir+json');

    var response = client.execute(postRequest);
    var responseBody = Packages.org.apache.commons.io.IOUtils.toString(response.getEntity().getContent(), 'UTF-8');

    // Log the response from the FHIR server
    logger.info("FHIR Server Response: " + responseBody);

    // Check the response status code
    if (response.getStatusLine().getStatusCode() != 201) {
        throw new Error("Failed to post FHIR Patient resource. Status code: " + response.getStatusLine().getStatusCode());
    }

} catch (e) {
    logger.error("Error processing ADT^A01 message and posting to FHIR server: " + e);
    throw e;
}
```

