public class HL7v2MessageRouter {

    // Constants for API endpoints and authentication details
    private static final String ADT_A01_ENDPOINT = "http://example.com/api/admissions";
    private static final String ORU_R01_ENDPOINT = "https://lab.example.com/api/results";
    private static final String AUTH_TOKEN = "your-auth-token"; // Replace with your actual token

    public String transform(String hl7Message) {
        try {
            // Extract the event type from the HL7 message
            String eventType = extractEventType(hl7Message);

            if ("ADT^A01".equals(eventType)) {
                return routeToAdmissions(hl7Message);
            } else if ("ORU^R01".equals(eventType)) {
                return routeToLabResults(hl7Message);
            } else {
                throw new IllegalArgumentException("Unsupported event type: " + eventType);
            }
        } catch (Exception e) {
            // Log the error and return an error message
            logError(e.getMessage());
            return "Error processing HL7 message: " + e.getMessage();
        }
    }

    private String extractEventType(String hl7Message) throws Exception {
        // Extract MSH-9 event type from the HL7 message
        int mshIndex = hl7Message.indexOf("MSH|^~\\&|");
        if (mshIndex == -1) {
            throw new IllegalArgumentException("Invalid HL7 message format");
        }
        String mshSegment = hl7Message.substring(mshIndex);
        int eventTypeIndex = mshSegment.indexOf("EVN|A01") + 4; // ADT^A01
        if (eventTypeIndex == -1) {
            eventTypeIndex = mshSegment.indexOf("EVN|R01"); // ORU^R01
        }
        if (eventTypeIndex == -1) {
            throw new IllegalArgumentException("Event type not found in HL7 message");
        }
        int caretIndex = mshSegment.indexOf("^", eventTypeIndex);
        return mshSegment.substring(eventTypeIndex, caretIndex);
    }

    private String routeToAdmissions(String hl7Message) throws Exception {
        URL url = new URL(ADT_A01_ENDPOINT);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/json");
        connection.setRequestProperty("Authorization", "Bearer " + AUTH_TOKEN);
        connection.setDoOutput(true);

        try (java.io.OutputStream os = connection.getOutputStream()) {
            byte[] input = hl7Message.getBytes("utf-8");
            os.write(input, 0, input.length);           
        }

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            return "ADT^A01 message routed successfully";
        } else {
            throw new Exception("Failed to route ADT^A01 message. Response code: " + responseCode);
        }
    }

    private String routeToLabResults(String hl7Message) throws Exception {
        URL url = new URL(ORU_R01_ENDPOINT);
