import ca.uhn.hl7v2.model.Message;
import ca.uhn.hl7v2.model.v26.segment.ADT_A01;
import ca.uhn.hl7v2.model.v26.segment.MSH;
import ca.uhn.hl7v2.model.v26.segment.PID;
import org.mirth.connect.donkey.model.message.MessagePart;
import org.mirth.connect.userutil.MessageUtil;

public class ADTErrorHandler {

    public void transform(Message message) {
        try {
            MSH mshSegment = (MSH) message.get("MSH");
            String messageId = mshSegment.getMessageControlID().getValue();

            ADT_A01 adtMessage = (ADT_A01) message;
            PID pidSegment = adtMessage.getPATIENT_RESULT().getPATIENT().getPID();
            String ssn = pidSegment.getPatientIdentifierList(0).getIDNumber().getValue();

            if (ssn == null || ssn.isEmpty()) {
                sendErrorAlert(messageId, "SSN is missing");
            }
        } catch (Exception e) {
            // Log the error and continue processing
            System.err.println("Error in ADTErrorHandler: " + e.getMessage());
        }
    }

    private void sendErrorAlert(String messageId, String errorDescription) {
        try {
            // Create the JSON payload for the email alert
            String jsonPayload = "{\"messageId\":\"" + messageId + "\", \"errorDescription\":\"" + errorDescription + "\"}";

            // Send the email alert using the /api/error/send endpoint
            // Replace "http://your-api-endpoint/api/error/send" with your actual API endpoint
            String url = "http://your-api-endpoint/api/error/send";
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(jsonPayload))
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            System.out.println("Email alert sent with status code: " + response.statusCode());

        } catch (Exception e) {
            // Log the error
            System.err.println("Error sending email alert: " + e.getMessage());
        }
    }
}
