To convert an HL7v2.5 ADT^A01 message to an FHIR Patient resource and post it to a remote healthcare system's RESTful API, you can use Mirth Connect along with JavaScript for the transformation logic. Below is a sample script that demonstrates how to achieve this:

```javascript
// Import necessary libraries
var HL7Util = Packages.ca.uhn.hl7v2.util.HL7Util;
var FHIRUtil = Packages.org.hl7.fhir.r4.utils.FHIRUtil;

// Function to convert PID segment to FHIR name
function convertPIDtoFHIRName(pid) {
    var givenName = pid.getField(3);
    var familyName = pid.getField(4);
    return [
        {
            "given": [givenName],
            "family": familyName
        }
    ];
}

// Function to convert PID segment to FHIR birthDate
function convertPIDtoFHIRBirthDate(pid) {
    var birthDate = pid.getField(7);
    return birthDate;
}

// Function to convert PID segment to FHIR maritalStatus
function convertPIDtoFHIRMaritalStatus(pid, mappingDict) {
    var maritalStatus = pid.getField(18);
    var code = mappingDict[maritalStatus];
    if (code) {
        return {
            "coding": [
                {
                    "code": code,
                    "display": maritalStatus
                }
            ]
        };
    } else {
        throw new Error("Invalid marital status: " + maritalStatus);
    }
}

// Function to convert PV1 segment to FHIR address
function convertPV1toFHIRAddress(pv1) {
    var line = pv1.getField(4);
    var city = pv1.getField(5);
    return [
        {
            "line": [line],
            "city": city
        }
    ];
}

// Main transformation function
function transform(message, properties) {
    // Get the ADT^A01 message
    var adtMessage = new Packages.ca.uhn.hl7v2.model.v25.message.ADT_A01(message);

    // Extract PID segment
    var pid = adtMessage.getPATIENT_RESULT().getPATIENT().getPID();
    var name = convertPIDtoFHIRName(pid);
    var birthDate = convertPIDtoFHIRBirthDate(pid);
    var maritalStatus = convertPIDtoFHIRMaritalStatus(pid, properties.maritalStatusMapping);

    // Extract PV1 segment
    var pv1 = adtMessage.getPATIENT_RESULT().getPATIENT().getPV1();
    var address = convertPV1toFHIRAddress(pv1);

    // Create FHIR Patient resource
    var fhirPatient = {
        "resourceType": "Patient",
        "name": name,
        "birthDate": birthDate,
        "maritalStatus": maritalStatus,
        "address": address
    };

    return JSON.stringify(fhirPatient);
}

// Error handling and logging
try {
    var transformedMessage = transform(message, properties);
    logger.info("Transformed FHIR Patient resource: " + transformedMessage);

    // Post the FHIR Patient resource to the remote healthcare system's RESTful API
    var url = "https://api.healthsystem.com/fhir/Patient";
    var headers = {
        "Content-Type": "application/json"
    };
    var response = new Packages.java.net.HttpURLConnection(new Packages.java.net.URL(url));
    response.setRequestMethod("POST");
    response.setRequestProperty("Content-Type", "application/json");
    response.setDoOutput(true);
    var outputStream = response.getOutputStream();
    outputStream.write(transformedMessage.getBytes());
    outputStream.flush();
    outputStream.close();

    if (response.getResponseCode() == 201) {
        logger.info("FHIR Patient resource posted successfully.");
    } else {
        logger.error("Failed to post FHIR Patient resource. Response code: " + response.getResponseCode());
    }
} catch (e) {
    logger.error("Error during transformation or posting: " + e.message);
}
