// Source Connector: HL7 Listener
// Destination Connector: HTTP Sender

function handleHL7Message(msg, meta) {
    try {
        // Parse the HL7 message
        var hl7Parser = new com.mirth.connect.model.message.HL7MessageParser();
        var parsedMessage = hl7Parser.parse(msg);

        // Extract necessary information from the ORC segment
        var orcSegment = parsedMessage.getSegment("ORC");
        if (orcSegment && orcSegment.getField(2).getValue() === "DISCHARGE") {
            var patientName = parsedMessage.getSegment("PID").getField(5).getValue();
            var dateOfBirth = parsedMessage.getSegment("PID").getField(7).getValue();
            var roomNumber = parsedMessage.getSegment("PV1").getField(4).getValue();

            // Trigger email notification
            sendEmailNotification(patientName, dateOfBirth, roomNumber);
        }
