        var emailServiceUrl = "https://api.exampleemail.com/send";
        var requestBody = JSON.stringify({
            to: "recipient@example.com",
            subject: "Patient Discharge Summary",
            body: `Patient Name: ${patientName}\nDate of Birth: ${dateOfBirth}\nRoom Number: ${roomNumber}`
        });

        var client = new java.net.URL(emailServiceUrl).openConnection();
        client.setRequestMethod("POST");
        client.setRequestProperty("Content-Type", "application/json");
        client.setDoOutput(true);

        var outputStream = client.getOutputStream();
        outputStream.write(requestBody.getBytes());
        outputStream.flush();

        var responseCode = client.getResponseCode();
        if (responseCode !== 200) {
            logError(`Failed to send email. Response code: ${responseCode}`);
        }
