```

### Step 2: Create the Server

Create a file named `server.js` and add the following code:

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const MongoClient = require('mongodb').MongoClient;
const MirthConnect = require('mirth-connect');

const app = express();
app.use(bodyParser.json());

// MongoDB connection string
const mongoUrl = 'mongodb://localhost:27017';
const dbName = 'patient_db';

// Mirth Connect configuration
const mirthHost = 'http://localhost:8080/mirth';
const mirthUsername = 'admin';
const mirthPassword = 'password';

let db;

MongoClient.connect(mongoUrl, { useNewUrlParser: true, useUnifiedTopology: true }, (err, client) => {
  if (err) throw err;
  db = client.db(dbName);
  console.log('Connected to MongoDB');
});

app.post('/api/hl7', async (req, res) => {
  try {
    const hl7Message = req.body.message;

    // Process HL7 message using Mirth Connect
    const mirthClient = new MirthConnect(mirthHost, mirthUsername, mirthPassword);
    const processedData = await mirthClient.processHL7(hl7Message);

    // Extract required fields from the processed data
    const { patientId, patientName, dateOfBirth, vitalSigns } = extractFields(processedData);

    // Insert data into MongoDB
    await db.collection('patients').insertOne({
      patientId,
      patientName,
      dateOfBirth,
      vitalSigns,
      timestamp: new Date()
    });

    res.status(201).send('Patient demographics inserted successfully');
  } catch (error) {
    console.error('Error processing HL7 message:', error);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});

function extractFields(processedData) {
  const { MSH, PID, OBX } = processedData;

  // Extract Patient ID (PID-3)
  const patientId = PID[3].split('^')[1];

  // Extract Patient Name (PID-5)
  const patientName = PID[5][0].split('^').join(' ');

  // Extract Date of Birth (PID-7)
  const dateOfBirth = PID[7].split('^')[1];

  // Extract Vital Signs (OBX-5)
  const vitalSigns = OBX.map(obx => obx.split('^')[5]);

  return { patientId, patientName, dateOfBirth, vitalSigns };
}
