```javascript
// Import required libraries
var fhir = require('fhirclient');

// Function to convert ISO 8601 birthdate to HL7 date format
function convertBirthdate(isoDate) {
    var date = new Date(isoDate);
    var year = date.getFullYear();
    var month = ("0" + (date.getMonth() + 1)).slice(-2); // Months are zero-indexed
    var day = ("0" + date.getDate()).slice(-2);
    return year + month + day;
}

// Main script logic
function main(msg, cfg) {
    try {
        // Extract patient birthdate from FHIR resource (assuming it's in the 'patient' object)
        var fhirClient = fhir.client(cfg.fhirServerUrl);
        var patient = await fhirClient.patient.read({ id: msg.meta.subject.reference.split('/')[1] });

        if (!patient || !patient.birthDate) {
            throw new Error('Patient birthdate not found in FHIR resource');
        }

        // Convert ISO 8601 birthdate to HL7 date format
        var hl7Birthdate = convertBirthdate(patient.birthDate);

        // Update the ADT message with the new birthdate
        msg.MSH.MSA.MSA1 = 'AA'; // Acknowledgment code (Accept)
        msg.PATIENT.ADM.ADM3.BDTS = hl7Birthdate; // Set the new birthdate in the ADT message

        return msg;
    } catch (error) {
        logger.error('Error converting birthdate: ' + error.message);
        throw error;
    }
}

// Export the main function
module.exports = {
    main: main
};
```

