        id: pidPatientID,
        meta: {
            versionId: mshControlID
        },
        birthDate: fhirBirthdate
    };

    return patientResource;
}

// Function to format HL7 v2 date to FHIR format (YYYY-MM-DD)
function formatDate(hl7Date) {
    if (!hl7Date || hl7Date.length !== 8) {
        throw new Error("Invalid HL7 date format");
    }

    var year = hl7Date.substring(0, 4);
    var month = hl7Date.substring(4, 6);
    var day = hl7Date.substring(6, 8);

    return `${year}-${month}-${day}`;
}

