        var oxygenSaturationThresholds = { min: 95, max: 100 };

        // Check vital sign values
        if (observationType === "Heart Rate") {
            if (parseFloat(observationValue) < heartRateThresholds.min || parseFloat(observationValue) > heartRateThresholds.max) {
                sendAlert(patientID, observationType, observationValue);
            }
        } else if (observationType === "Blood Pressure") {
            var bpParts = observationValue.split("/");
            var systolic = parseInt(bpParts[0], 10);
            var diastolic = parseInt(bpParts[1], 10);
            if (systolic < bloodPressureThresholds.min || systolic > bloodPressureThresholds.max ||
                diastolic < bloodPressureThresholds.min || diastolic > bloodPressureThresholds.max) {
                sendAlert(patientID, observationType, observationValue);
            }
        } else if (observationType === "Oxygen Saturation") {
            if (parseFloat(observationValue) < oxygenSaturationThresholds.min || parseFloat(observationValue) > oxygenSaturationThresholds.max) {
                sendAlert(patientID, observationType, observationValue);
            }
        }
    }
}

function sendAlert(patientID, vitalSignType, outOfRangeValue) {
    // Get patient's email address from the FHIR API
    var fhirURL = "https://api.healthcareprovider.com/fhir/vital-signs";
    var response = new java.net.URL(fhirURL).openConnection().getContent();
    var fhirData = JSON.parse(response);

    for (var i = 0; i < fhirData.entry.length; i++) {
        var entry = fhirData.entry[i];
        if (entry.resource.subject.reference === "Patient/" + patientID) {
            var email = entry.resource.telecom[0].value;
            break;
        }
    }

    // Construct alert message
    var timestamp = new Date().toISOString();
    var alertMessage = "Alert: Vital sign out of range\n" +
                        "Patient ID: " + patientID + "\n" +
                        "Timestamp: " + timestamp + "\n" +
                        "Vital Sign Type: " + vitalSignType + "\n" +
                        "Out-of-Range Value: " + outOfRangeValue;

    // Send alert message via messaging service API
    var messagingURL = "https://api.healthcareprovider.com/messaging";
    var postData = {
        to: email,
        subject: "Vital Sign Alert",
        body: alertMessage
    };
    var postRequest = new java.net.URL(messagingURL).openConnection();
    postRequest.setRequestMethod("POST");
    postRequest.setRequestProperty("Content-Type", "application/json");
    postRequest.setDoOutput(true);
    var outputStream = postRequest.getOutputStream();
    outputStream.write(JSON.stringify(postData));
    outputStream.flush();
    outputStream.close();

    // Handle errors
    try {
        var responseCode = postRequest.getResponseCode();
        if (responseCode !== 200) {
            throw new Error("Failed to send alert message. Response code: " + responseCode);
        }
    } catch (e) {
        logger.error("Error sending alert message: " + e.message);
    }
}
```

### Explanation:
1. **handle HL7Message Function**:
   - Extracts the patient ID from the PID segment.
   - Iterates through OBX segments to check vital sign values against predefined thresholds.

2. **sendAlert Function**:
   - Fetches the patient's email address from the FHIR API.
   - Constructs an alert message including patient ID, timestamp, vital sign type, and out-of-range value.
   - Sends the alert message via the messaging service API using a POST request.

### Error Handling:
- The script includes basic error handling for network requests to the messaging service API. If the response code is not 200, it logs an error message.

