```javascript
// Import necessary libraries
var hl7 = require('hl7');
var fhir = require('fhir');

// Function to parse HL7v2 message and create FHIR resource
function transformHL7toFHIR(hl7Message) {
    var parsedMessage = hl7.parse(hl7Message);

    // Extract patient identifier (PID-3)
    var patientIdentifier = parsedMessage.PID[3][1].toString();

    // Extract encounter identifier (PV1-2)
    var encounterIdentifier = parsedMessage.PV1[2][0].toString();

    // Create FHIR Patient resource
    var fhirPatient = new fhir.Patient({
        resourceType: 'Patient',
        id: patientIdentifier,
        identifier: [
            {
                system: 'http://hospitalidp.com/patient-identifier',
                value: patientIdentifier
            }
        ]
    });

    // Create FHIR Encounter resource
    var fhirEncounter = new fhir.Encounter({
        resourceType: 'Encounter',
        id: encounterIdentifier,
        identifier: [
            {
                system: 'http://hospitalidp.com/encounter-identifier',
                value: encounterIdentifier
            }
        ],
        meta: {
            tag: [
                {
                    system: 'http://hospitalidp.com/encounter-status',
                    code: 'active'
                }
            ]
        },
        patient: {
            reference: 'Patient/' + patientIdentifier
        }
    });

    return {
        fhirPatient: fhirPatient,
        fhirEncounter: fhirEncounter
    };
}

// Main transformation function
function transform(message) {
    var hl7Message = message.get('message');
    var fhirResources = transformHL7toFHIR(hl7Message);

    // Send FHIR resources to the hospital's LIS system using FHIR API
    try {
        var tokenResponse = sendOAuthRequest();
        var accessToken = tokenResponse.access_token;

        sendFHIRResource(accessToken, 'http://hospitalidp.com/fhir/Patient', fhirResources.fhirPatient);
        sendFHIRResource(accessToken, 'http://hospitalidp.com/fhir/Encounter', fhirResources.fhirEncounter);
    } catch (error) {
        logger.error('Error during FHIR resource transmission: ' + error.message);
        throw error;
    }

    return message;
}

// Function to send OAuth 2.0 request
function sendOAuthRequest() {
    var url = 'https://hospitalidp.com/oauth/token';
    var headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    };
    var body = 'grant_type=client_credentials&client_id=your-client-id&client_secret=your-client-secret';

    try {
        var response = new java.net.URL(url).openConnection();
        response.setRequestMethod('POST');
        response.setDoOutput(true);
        response.setRequestProperty('Content-Type', 'application/x-www-form-urlencoded');

        var outputStream = response.getOutputStream();
        outputStream.write(body.getBytes());
        outputStream.flush();
        outputStream.close();

        var inputStream = response.getInputStream();
        var reader = new java.io.BufferedReader(new java.io.InputStreamReader(inputStream));
        var jsonResponse = '';
        var line;
        while ((line = reader.readLine()) != null) {
            jsonResponse += line;
        }
        reader.close();

        return JSON.parse(jsonResponse);
    } catch (error) {
        logger.error('Error during OAuth request: ' + error.message);
        throw error;
    }
}

// Function to send FHIR resource
function sendFHIRResource(accessToken, url, fhirResource) {
    var headers = {
        'Authorization': 'Bearer ' + accessToken,
        'Content-Type': 'application/fhir+json'
    };

    try {
        var response = new java.net.URL(url).openConnection();
        response.setRequestMethod('POST');
        response.setDoOutput(true);

        for (var header in headers) {
            response.setRequestProperty(header, headers[header]);
        }

        var outputStream = response.getOutputStream();
        outputStream.write(JSON.stringify(fhirResource).getBytes());
        outputStream.flush();
        outputStream.close();

        var inputStream = response.getInputStream();
        var reader = new java.io.BufferedReader(new java.io.InputStreamReader(inputStream));
        var jsonResponse = '';
        var line;
        while ((line = reader.readLine()) != null) {
            jsonResponse += line;
        }
        reader.close();

        logger.info('FHIR resource sent successfully: ' + jsonResponse);
    } catch (error) {
        logger.error('Error during FHIR resource transmission: ' + error.message);
        throw error;
    }
}
