// Define a function to parse HL7 v2.5 ORU^R01 message and convert it to FHIR STU3 JSON format
function hl7ToFhir(json) {
    var fhir = {
        resourceType: "Observation",
        status: "final",
        category: [
            { coding: [{ system: "http://terminology.hl7.org/CodeSystem/observation-category", code: "laboratory" }] }
        ],
        subject: {
            reference: "Patient/" + json.PID[3][1].toString() // Assuming PID-3-1 is the patient ID
        },
        effectiveDateTime: json.OBX[1][5].toString(), // Assuming OBX-5 is the observation date/time
        code: {
            coding: [
                { system: "http://loinc.org", code: json.OBX[3][0].toString() } // Assuming OBX-3-1 is the LOINC code
            ]
        },
        valueQuantity: {
            value: parseFloat(json.OBX[5][1].toString()), // Assuming OBX-5-1 is the observation result value
            unit: json.OBX[6][0].toString(), // Assuming OBX-6-1 is the observation result units
            system: "http://unitsofmeasure.org",
            code: json.OBX[6][3].toString() // Assuming OBX-6-3 is the UCUM code
        }
    };

    return JSON.stringify(fhir);
}

// Define a function to send FHIR JSON data to an external FHIR server using POST method with basic authentication
function sendToFhirServer(json) {
    var url = "https://api.healthcareprovider.com/fhir/submit";
    var username = "healthcareuser";
    var password = "healthpass123";

    // Create a new HTTP request object
    var http = new Packages.java.net.URL(url).openConnection();
    http.setRequestMethod("POST");
    http.setDoOutput(true);
    http.setRequestProperty("Content-Type", "application/json");

    // Set basic authentication credentials
    var auth = username + ":" + password;
    var encodedAuth = Packages.java.util.Base64.getEncoder().encodeToString(auth.getBytes());
    http.setRequestProperty("Authorization", "Basic " + encodedAuth);

    // Write the JSON data to the HTTP request body
    var outputStream = http.getOutputStream();
    outputStream.write(json.getBytes());
    outputStream.flush();
    outputStream.close();

    // Get the response from the FHIR server
    var inputStream = http.getInputStream();
    var reader = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(inputStream));
    var response = "";
    var line;
    while ((line = reader.readLine()) != null) {
        response += line;
    }
    reader.close();

    // Check if the HTTP request was successful
    if (http.getResponseCode() == 201) {
        return "Observation submitted successfully: " + response;
    } else {
        return "Failed to submit observation: " + http.getResponseMessage();
    }
}

// Define a function to handle incoming HL7 messages and process them
function handleMessage(message) {
    try {
        // Parse the HL7 message into JSON format
        var json = Packages.com.mirth.connect.server.util.HL7Util.parseHL7(message, true);

        // Convert the HL7 message to FHIR STU3 JSON format
        var fhirJson = hl7ToFhir(json);

        // Send the FHIR JSON data to an external FHIR server using POST method with basic authentication
        var response = sendToFhirServer(fhirJson);

        // Log the response from the FHIR server
        logger.info(response);
    } catch (e) {
        // Log any errors that occur during message processing
        logger.error("Error processing HL7 message: " + e.message, e);
    }
}

// Set the channel to use this script for incoming messages
setHandler(handleMessage);
