    @PostMapping("/process")
    public ResponseEntity<String> processDicomMessage(@RequestBody String hl7Message) {
        try {
            // Parse the HL7 message
            Message message = new Message(hl7Message);

            // Extract MSH segment (Message Header)
            MSH mshSegment = message.getMSH();
            String messageId = mshSegment.getMessageControlID().getID().getValue();

            // Log the message with its unique MessageID
            logMessage(messageId, "Received DICOM message");

