var email = require('emailjs');

// Function to parse DICOM message and extract critical result information
function parseDicomMessage(message) {
    var dataset = dicomParser.parseDataset(new Uint8Array(message));

    // Check if the result is critical
    var criticalFlag = dataset.string(0x00540408);
    if (criticalFlag === 'CRITICAL') {
        var patientID = dataset.string(0x00100020);
        var studyInstanceUID = dataset.string(0x0020000D);
        var seriesInstanceUID = dataset.string(0x0020000E);
