    "databaseUrl": "jdbc:postgresql://localhost:5432/mydb",
    "databaseUser": "myuser",
    "databasePassword": "mypassword"
};

// Define the DICOM message parsing function
function parseDicomMessage(dicomMessage) {
    var dicomParser = new com.pixelmed.dicom.DicomInputStream(new java.io.ByteArrayInputStream(dicomMessage));
    var patientID = dicomParser.getStringValue(0x0010, 0x0020);
    var name = dicomParser.getStringValue(0x0010, 0x0010);
    var age = dicomParser.getStringValue(0x0010, 0x0012);
    return {
        patientID: patientID,
        name: name,
        age: age
    };
}

// Define the database query function
function queryDatabase(patientID) {
    var connection = null;
    try {
        connection = java.sql.DriverManager.getConnection(channelProperties.databaseUrl, channelProperties.databaseUser, channelProperties.databasePassword);
        var statement = connection.createStatement();
        var resultSet = statement.executeQuery("SELECT * FROM patients WHERE patient_id = '" + patientID + "'");
        if (resultSet.next()) {
            return resultSet;
        }
    } catch (e) {
        logger.error("Database query error: " + e.message);
    } finally {
        if (connection) {
            connection.close();
        }
    }
}

// Define the database update function
function updateDatabase(patientID, name, age) {
    var connection = null;
    try {
        connection = java.sql.DriverManager.getConnection(channelProperties.databaseUrl, channelProperties.databaseUser, channelProperties.databasePassword);
        var statement = connection.createStatement();
        if (queryDatabase(patientID)) {
            // Update existing record
            statement.executeUpdate("UPDATE patients SET name = '" + name + "', age = " + age + " WHERE patient_id = '" + patientID + "'");
        } else {
            // Insert new record
            statement.executeUpdate("INSERT INTO patients (patient_id, name, age) VALUES ('" + patientID + "', '" + name + "', " + age + ")");
        }
    } catch (e) {
        logger.error("Database update error: " + e.message);
    } finally {
        if (connection) {
            connection.close();
        }
    }
}

// Define the status update function
function updateStatus(messageID, status) {
    var connection = null;
    try {
        connection = java.sql.DriverManager.getConnection(channelProperties.databaseUrl, channelProperties.databaseUser, channelProperties.databasePassword);
        var statement = connection.createStatement();
        statement.executeUpdate("UPDATE dicom_messages SET status = '" + status + "' WHERE message_id = '" + messageID + "'");
    } catch (e) {
        logger.error("Status update error: " + e.message);
    } finally {
        if (connection) {
            connection.close();
        }
    }
}

// Main channel script
function handleRequest(message, properties) {
    try {
        var dicomMessage = message.getByteArray();
        var parsedMessage = parseDicomMessage(dicomMessage);

        updateDatabase(parsedMessage.patientID, parsedMessage.name, parsedMessage.age);
        updateStatus(properties.messageId, 'Processed');

        return "DICOM message processed successfully";
    } catch (e) {
        logger.error("Error processing DICOM message: " + e.message);
        return "Error processing DICOM message";
    }
}
```

