// Function to fetch completed studies from DICOMweb
function fetchCompletedStudies() {
    try {
        var client = new java.net.URL(dicomWebEndpoint).openConnection();
        client.setRequestMethod('GET');
        client.setRequestProperty('Accept', 'application/dicom+json');
        client.setDoOutput(true);

        var outputStream = client.getOutputStream();
        var writer = new java.io.OutputStreamWriter(outputStream);
