   ```javascript
   // Import necessary libraries
   importPackage(Packages.java.io);
   importPackage(Packages.ca.uhn.hl7v2.model.v25.message);
   importPackage(Packages.ca.uhn.hl7v2.model.v25.segment);

   // Get the message
   var msg = channelMap.get("msg");

   try {
       // Extract Study Instance UID and Patient ID from DICOM header
       var studyInstanceUID = msg.getField(0, 0, 1, 0).getValue();
       var patientID = msg.getField(0, 2, 1, 0).getValue();

       if (!studyInstanceUID || !patientID) {
           throw new Error("Malformed DICOM message: Missing Study Instance UID or Patient ID");
