       postMethod.setRequestBody(jsonPayload);

       var responseCode = httpUtil.executeMethod(postMethod);

       if (responseCode != 200) {
           throw new Error("Failed to update EHR system: HTTP Status Code " + responseCode);
       }

       // Log the DICOM details
       logger.info("Received DICOM message with Study Instance UID: " + studyInstanceUID + " and Patient ID: " + patientID);

   } catch (e) {
       logger.error("Error processing DICOM message: " + e.message);
       throw e;
   }
   ```

